class TestProcessData:
    """测试 process_data 函数"""

    def test_process_data_normal(self):
        """正常用例：标准字典数据转换"""
        data = {"name": "john", "city": "beijing"}
        result = process_data(data)
        assert result == {"name": "JOHN", "city": "BEIJING"}

    def test_process_data_empty(self):
        """边界用例：空字典"""
        data = {}
        result = process_data(data)
